using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Windows;using System.Windows.Media;using System.Windows.Input;
public sealed class QuotaTimeline:FrameworkElement {
 public DateTime Start,End;public QuotaAuditEvent[] Events=new QuotaAuditEvent[0];double hoverX=-1,hoverY=80;public QuotaTimeline(){Height=210;MinWidth=600;MouseMove+=(s,e)=>{var point=e.GetPosition(this);hoverY=point.Y;HoverAt(point.X);};MouseLeave+=(s,e)=>{hoverX=-1;ToolTip=null;InvalidateVisual();};System.Windows.Automation.AutomationProperties.SetName(this,"额度事件时间轴");}
 internal void HoverAt(double x){if(End<=Start||x<78||x>ActualWidth-30){hoverX=-1;ToolTip=null;InvalidateVisual();return;}hoverX=x;double width=Math.Max(1,ActualWidth-108);DateTime cursor=Start.AddSeconds((x-78)/width*(End-Start).TotalSeconds);var near=Events.Where(v=>(v.Kind=="reset-observed"||v.Kind=="wake-ready"||v.Kind=="wake-result")&&v.Utc.ToLocalTime()>=Start&&v.Utc.ToLocalTime()<End&&Math.Abs(78+((v.Utc.ToLocalTime()-Start).TotalSeconds/(End-Start).TotalSeconds)*width-x)<=8).OrderBy(v=>v.Utc).ToArray();ToolTip=cursor.ToString("yyyy-MM-dd HH:mm")+(near.Length==0?"\n附近无事件":"\n"+String.Join("\n",near.Select(QuotaAudit.Describe)));InvalidateVisual();}
 static void Label(DrawingContext dc,string text,double x,double y,Brush brush,double dpi,double size){dc.DrawText(new FormattedText(text,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),size,brush,dpi),new Point(x,y));}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);ChartHover.Background(dc,ActualWidth,ActualHeight);if(End<=Start||ActualWidth<150)return;double dpi=VisualTreeHelper.GetDpi(this).PixelsPerDip,left=78,width=ActualWidth-108;var muted=TryFindResource("DeskMuted") as Brush??Brushes.SlateGray;var line=TryFindResource("DeskLine") as Brush??Brushes.Gray;var inset=TryFindResource("DeskInset") as Brush??Brushes.Transparent;double[] ys={62,128};for(int lane=0;lane<2;lane++){dc.DrawRoundedRectangle(inset,new Pen(line,.65),new Rect(0,ys[lane]-24,ActualWidth-4,48),10,10);Label(dc,lane==0?"五小时":"周额度",8,ys[lane]-8,muted,dpi,12);dc.DrawLine(new Pen(line,1),new Point(left,ys[lane]),new Point(left+width,ys[lane]));}int days=Math.Max(1,(End-Start).Days);for(int i=0;i<days;i++){double x=left+width*i/days;dc.DrawLine(new Pen(line,.45),new Point(x,35),new Point(x,153));if(i%Math.Max(1,(int)Math.Ceiling(days/Math.Max(1,Math.Min(9,width/48))))==0)Label(dc,Start.AddDays(i).ToString("MM/dd"),x-12,166,muted,dpi,10);}var events=Events.Where(x=>x.Utc.ToLocalTime()>=Start&&x.Utc.ToLocalTime()<End&&(x.Kind=="reset-observed"||x.Kind=="wake-ready"||x.Kind=="wake-result")).OrderBy(x=>x.Utc).ToArray();foreach(var e in events){double x=left+width*(e.Utc.ToLocalTime()-Start).TotalSeconds/(End-Start).TotalSeconds;var brush=e.Kind=="reset-observed"?Brushes.Gold:e.Kind=="wake-ready"?Brushes.DeepSkyBlue:Brushes.MediumPurple;for(int lane=0;lane<2;lane++){if(!(e.Windows??"").Contains(lane==0?"五小时":"周额度"))continue;if(e.Kind=="reset-observed")ChartHover.ResetMark(dc,x,ys[lane]);else dc.DrawEllipse(brush,new Pen(Brushes.White,.6),new Point(x,ys[lane]),5,5);}}if(events.Length==0)Label(dc,"此时间范围没有记录",left+10,94,muted,dpi,12);if(hoverX>=left&&hoverX<=left+width)ChartHover.Show(dc,this,hoverX,hoverY,left,left+width,33,154,ToolTip as string);}
}
